def _seconds(text: str) -> float:
    words = len(re.findall(r"\S+", text))
    return round(max(8.0, min(30.0, words / SPEAKING_WPM * 60.0 + 2.5)), 1)


def main() -> None:
    spec = json.loads(ENGLISH_SPEC.read_text(encoding="utf-8"))
    missing = [s["scene_key"] for s in spec["scenes"] if s["scene_key"] not in NARRATION]
    if missing:
        raise SystemExit(f"No Hindi narration for: {missing}")

    for scene in spec["scenes"]:
        key = scene["scene_key"]
        scene["narration"] = NARRATION[key]
        scene["target_duration_s"] = _seconds(NARRATION[key])
        if key in CHAPTERS:
            scene["chapter_title"] = CHAPTERS[key]
        else:
            scene.pop("chapter_title", None)
        if key in LOWER:
            scene["lower_third"] = LOWER[key]
        else:
            scene.pop("lower_third", None)

    spec["name"] = "The Laws of Human Nature, Part 1 of 2 (Hindi)"
    spec["voice"] = "kokoro:hm_omega"
    spec["title"] = TITLE
    spec["logline"] = LOGLINE
    spec["synopsis"] = SYNOPSIS
    spec["brief"] = BRIEF
    spec["finishing"]["end_card"] = END_CARD
    spec["target_duration_s"] = round(sum(s["target_duration_s"] for s in spec["scenes"]))

    HINDI_SPEC.parent.mkdir(parents=True, exist_ok=True)
    HINDI_SPEC.write_text(json.dumps(spec, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"wrote {HINDI_SPEC}: {len(spec['scenes'])} scenes, about {spec['target_duration_s']} s")


if __name__ == "__main__":
    main()
